<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api'

type FileRecord = { file_id: string; original_name: string }
type InspectionColumn = { header: string; business_hint?: string | null }
type FieldSide = { fields: string[]; combine: 'concat' | 'coalesce' | 'best_of'; separator: string; pipeline: Array<Record<string, unknown>> }
type Rule = { id: string; source: FieldSide; target: FieldSide; matcher: string; weight: number; critical: boolean; matcher_options?: Record<string, unknown> }
type MappingRow = { source: string; targets: string }
type FieldScore = { rule_id: string; score: number; weight: number; source_value: string; target_value: string; critical: boolean; conflict: boolean }
type Candidate = { rank: number; target_group_code: string; score: number; critical_conflict: boolean; target_payload: Record<string, unknown>; field_scores: FieldScore[] }
type WorkbenchItem = { source_row_id: string; source_id: string; source_payload: Record<string, unknown>; top1_group_code?: string | null; top1_score: number; second_score: number; score_gap: number; critical_conflict: boolean }
type ReviewSummary = { pending_review: number; confirmed: number; unmatched: number; automatic_matched: number }

const route = useRoute(), router = useRouter()
const active = ref(0), draftId = ref(''), name = ref('')
const source = ref<FileRecord | null>(null), target = ref<FileRecord | null>(null)
const sourceColumns = ref<string[]>([]), targetColumns = ref<string[]>([])
const sourceIdColumn = ref(''), groupCodeColumn = ref(''), catalogVersionId = ref('')
const rules = ref<Rule[]>([]), scopeMode = ref<'GLOBAL' | 'STRICT' | 'MAPPED'>('GLOBAL')
const scopeSourceField = ref(''), scopeTargetField = ref(''), scopeMappingRows = ref<MappingRow[]>([])
const successThreshold = ref(88), reviewThreshold = ref(75), topN = ref(5)
const advanced = ref(false), task = ref<any>(null), progress = ref<any>(null), busy = ref(false)
const dryRunBusy = ref(false), dryRunRows = ref<any[]>([]), dryRunSummary = ref<any>(null)
const reviewSummary = ref<ReviewSummary>({ pending_review: 0, confirmed: 0, unmatched: 0, automatic_matched: 0 })
const workbenchItems = ref<WorkbenchItem[]>([]), selectedRows = ref<WorkbenchItem[]>([])
const filterMode = ref('all')
const drawerVisible = ref(false), drawerItem = ref<WorkbenchItem | null>(null), candidates = ref<Candidate[]>([]), candidateIndex = ref(0)
let saveTimer: number | undefined
let pollTimer: number | undefined

const summary = computed(() => `参与字段：${rules.value.length} 个｜总权重：${rules.value.reduce((sum, rule) => sum + Number(rule.weight || 0), 0)}（运行时归一）｜自动匹配阈值：${successThreshold.value} 分｜人工确认区间：${reviewThreshold.value}～${successThreshold.value} 分｜候选输出：Top ${topN.value}`)
const currentCandidate = computed(() => candidates.value[candidateIndex.value] ?? null)
const scopeReady = computed(() => scopeMode.value === 'GLOBAL' || (!!scopeSourceField.value && !!scopeTargetField.value && (scopeMode.value !== 'MAPPED' || scopeMappingRows.value.some(row => row.source.trim() && row.targets.trim()))))
const rulesReady = computed(() => !!sourceIdColumn.value && rules.value.length > 0 && rules.value.every(rule => rule.source.fields.length && rule.target.fields.length && rule.weight >= 0 && rule.weight <= 100 && rule.matcher !== 'semantic') && reviewThreshold.value < successThreshold.value && scopeReady.value)
const finalTotal = computed(() => reviewSummary.value.pending_review + reviewSummary.value.confirmed + reviewSummary.value.unmatched + reviewSummary.value.automatic_matched)

function columnsFromInspection(inspection: any): InspectionColumn[] { return inspection.sheets.find((item: any) => item.sheet_name === inspection.recommended_sheet)?.columns ?? [] }
function findHint(columns: InspectionColumn[], hint: string): string { return columns.find(column => column.business_hint === hint)?.header ?? '' }
async function loadFile(fileId: string, kind: 'source' | 'target'): Promise<void> {
  const response = (await api.get(`/files/${fileId}/inspection`)).data; const columns = columnsFromInspection(response.inspection)
  if (kind === 'source') { source.value = response.file; sourceColumns.value = columns.map(column => column.header); if (!sourceIdColumn.value) sourceIdColumn.value = findHint(columns, 'source_id') || sourceColumns.value[0] || '' }
  else { target.value = response.file; targetColumns.value = columns.map(column => column.header); if (!groupCodeColumn.value) groupCodeColumn.value = findHint(columns, 'group_code') || targetColumns.value[0] || '' }
}
async function ensureDraft(): Promise<void> { if (draftId.value) return; const draft = (await api.post('/task-drafts', { name: name.value || '未命名匹配任务' })).data; draftId.value = draft.draft_id; await router.replace({ path: '/tasks/new', query: { draft: draftId.value } }) }
async function upload(kind: 'source' | 'target', selected: any): Promise<void> {
  busy.value = true
  try { const form = new FormData(); form.append('role', kind); form.append('file', selected.raw); const response = (await api.post('/files/upload', form)).data; const columns = columnsFromInspection(response.inspection); if (kind === 'source') { source.value = response.file; sourceColumns.value = columns.map((column) => column.header); sourceIdColumn.value = findHint(columns, 'source_id') || sourceColumns.value[0] || '' } else { target.value = response.file; targetColumns.value = columns.map((column) => column.header); groupCodeColumn.value = findHint(columns, 'group_code') || targetColumns.value[0] || ''; catalogVersionId.value = '' } }
  catch (error) { ElMessage.error((error as Error).message) } finally { busy.value = false }
}
function defaultRule(): Rule { const sourceField = sourceColumns.value.find(column => column !== sourceIdColumn.value) ?? sourceColumns.value[0] ?? ''; const targetField = targetColumns.value.find(column => column !== groupCodeColumn.value) ?? targetColumns.value[0] ?? ''; return { id: `rule_${rules.value.length + 1}`, source: { fields: sourceField ? [sourceField] : [], combine: 'concat', separator: ' ', pipeline: [] }, target: { fields: targetField ? [targetField] : [], combine: 'concat', separator: ' ', pipeline: [] }, matcher: 'fuzzy', weight: rules.value.length ? 50 : 80, critical: false } }
async function nextStepOne(): Promise<void> { await ensureDraft(); if (!source.value || !target.value || !groupCodeColumn.value || !sourceIdColumn.value) return; if (!catalogVersionId.value) { const catalog = (await api.post('/catalogs', { name: `${name.value || '任务'}-集团码目录`, source_file_id: target.value.file_id, group_code_column: groupCodeColumn.value })).data; catalogVersionId.value = catalog.version_id } await api.put(`/task-drafts/${draftId.value}/data`, { source_file_id: source.value.file_id, catalog_version_id: catalogVersionId.value, template_profile_id: null, template_profile_version: null }); if (!rules.value.length) rules.value = [defaultRule()]; active.value = 1; await saveRules() }
function scopeMapping(): Record<string, string[]> { const result: Record<string, string[]> = {}; for (const row of scopeMappingRows.value) { const sourceValue = row.source.trim(); if (!sourceValue) continue; result[sourceValue] = row.targets.split(/[,，]/).map(value => value.trim()).filter(Boolean) } return result }
function document(): Record<string, unknown> { return { source_id_column: sourceIdColumn.value, scope_mode: scopeMode.value, scope: { source_field: scopeSourceField.value || null, target_field: scopeTargetField.value || null, mapping: scopeMapping() }, rules: rules.value, decision: { success_threshold: successThreshold.value, review_enabled: true, review_threshold: reviewThreshold.value, top_n: topN.value }, advanced: {} } }
async function saveRules(): Promise<void> { if (!draftId.value || active.value !== 1 || !rules.value.length) return; await api.put(`/task-drafts/${draftId.value}/rules`, document()) }
function scheduleSave(): void { if (saveTimer) window.clearTimeout(saveTimer); saveTimer = window.setTimeout(() => void saveRules().catch(() => undefined), 500) }
function addRule(): void { rules.value.push(defaultRule()) }
function removeRule(index: number): void { rules.value.splice(index, 1) }
function addMapping(): void { scopeMappingRows.value.push({ source: '', targets: '' }) }
async function dryRun(): Promise<void> { if (!rulesReady.value) return; dryRunBusy.value = true; try { await saveRules(); const response = (await api.post(`/task-drafts/${draftId.value}/dry-run`, { sample_rows: 100 })).data; dryRunSummary.value = response.summary; dryRunRows.value = response.rows; ElMessage.success(`试算完成：${response.summary.total} 条`) } catch (error) { ElMessage.error((error as Error).message) } finally { dryRunBusy.value = false } }
async function start(): Promise<void> { if (!rulesReady.value) return; try { await saveRules(); task.value = (await api.post(`/task-drafts/${draftId.value}/start`)).data; active.value = 2; await router.replace(`/tasks/${task.value.task_id}`); startPolling() } catch (error) { ElMessage.error((error as Error).message) } }
function stopPolling(): void { if (pollTimer) window.clearInterval(pollTimer); pollTimer = undefined }
function startPolling(): void { stopPolling(); void pollProgress(); pollTimer = window.setInterval(() => void pollProgress(), 700) }
async function pollProgress(): Promise<void> { if (!task.value?.task_id) return; try { progress.value = (await api.get(`/tasks/${task.value.task_id}/progress`)).data; task.value = (await api.get(`/tasks/${task.value.task_id}`)).data; if (task.value.status === 'FAILED') { stopPolling(); ElMessage.error(task.value.error_message || '比对计算失败') } else if (task.value.status === 'COMPLETED') { stopPolling(); if (task.value.stage === 'REVIEW') { active.value = 3; await loadWorkbench() } else { active.value = 4; await loadReviewSummary() } } } catch (error) { stopPolling(); ElMessage.error((error as Error).message) } }
async function loadReviewSummary(): Promise<void> { if (!task.value?.task_id) return; reviewSummary.value = (await api.get(`/tasks/${task.value.task_id}/workbench/summary`)).data }
function filterParams(): Record<string, unknown> { if (filterMode.value === 'high') return { first_score_min: 90, critical_conflict: false }; if (filterMode.value === '80-90') return { first_score_min: 80, first_score_max: 90 }; if (filterMode.value === 'gap') return { gap_max: 5 }; if (filterMode.value === 'conflict') return { critical_conflict: true }; return {} }
async function loadWorkbench(): Promise<void> { if (!task.value?.task_id) return; const [summaryResponse, itemsResponse] = await Promise.all([api.get(`/tasks/${task.value.task_id}/workbench/summary`), api.get(`/tasks/${task.value.task_id}/workbench/items`, { params: { ...filterParams(), page: 1, page_size: 100 } })]); reviewSummary.value = summaryResponse.data; workbenchItems.value = itemsResponse.data.items; selectedRows.value = [] }
async function setFilter(mode: string): Promise<void> { filterMode.value = mode; await loadWorkbench() }
function onSelection(rows: WorkbenchItem[]): void { selectedRows.value = rows }
async function openCandidates(item: WorkbenchItem): Promise<void> { drawerItem.value = item; const response = (await api.get(`/tasks/${task.value.task_id}/items/${item.source_row_id}/candidates`)).data; candidates.value = response.candidates; candidateIndex.value = 0; drawerVisible.value = true }
async function confirmCandidate(item: WorkbenchItem, targetId?: string): Promise<void> { const targetIdValue = targetId || item.top1_group_code; if (!targetIdValue) return; await api.post(`/tasks/${task.value.task_id}/items/${item.source_row_id}/confirm`, { target_id: targetIdValue, comment: '' }); await loadWorkbench(); ElMessage.success('已确认候选') }
async function rejectItem(item: WorkbenchItem): Promise<void> { await api.post(`/tasks/${task.value.task_id}/items/${item.source_row_id}/reject`, { comment: '' }); await loadWorkbench(); ElMessage.success('已标记未匹配') }
async function confirmFromDrawer(): Promise<void> { if (!drawerItem.value || !currentCandidate.value) return; await confirmCandidate(drawerItem.value, currentCandidate.value.target_group_code); if (workbenchItems.value.length) await openCandidates(workbenchItems.value[0]); else drawerVisible.value = false }
async function rejectFromDrawer(): Promise<void> { if (!drawerItem.value) return; await rejectItem(drawerItem.value); if (workbenchItems.value.length) await openCandidates(workbenchItems.value[0]); else drawerVisible.value = false }
async function batchConfirm(): Promise<void> { if (!selectedRows.value.length) return; const response = (await api.post(`/tasks/${task.value.task_id}/workbench/batch-confirm-top1`, { source_row_ids: selectedRows.value.map(row => row.source_row_id) })).data; await loadWorkbench(); ElMessage.success(`成功确认 ${response.success.length} 条${response.failed.length ? `，失败 ${response.failed.length} 条` : ''}`) }
async function batchReject(): Promise<void> { if (!selectedRows.value.length) return; const response = (await api.post(`/tasks/${task.value.task_id}/workbench/batch-reject`, { source_row_ids: selectedRows.value.map(row => row.source_row_id) })).data; await loadWorkbench(); ElMessage.success(`成功标记 ${response.success.length} 条${response.failed.length ? `，失败 ${response.failed.length} 条` : ''}`) }
async function finalize(): Promise<void> { await loadReviewSummary(); let allow = false; if (reviewSummary.value.pending_review > 0) { try { await ElMessageBox.confirm(`仍有 ${reviewSummary.value.pending_review} 条待确认记录。继续后这些记录的最终集团码保持为空。`, '生成最终结果', { confirmButtonText: '继续生成', cancelButtonText: '返回处理', type: 'warning' }); allow = true } catch { return } } try { await api.post(`/tasks/${task.value.task_id}/finalize`, { allow_unresolved_review: allow }); task.value = (await api.get(`/tasks/${task.value.task_id}`)).data; active.value = 4; await loadReviewSummary(); ElMessage.success('最终结果已生成') } catch (error) { ElMessage.error((error as Error).message) } }
function downloadResult(): void { window.location.href = `/api/tasks/${task.value.task_id}/result` }
async function restoreDraft(id: string): Promise<void> { const draft = (await api.get(`/task-drafts/${id}`)).data; draftId.value = draft.draft_id; name.value = draft.name; if (draft.source_file_id) await loadFile(draft.source_file_id, 'source'); if (draft.catalog_version_id) { const catalog = (await api.get(`/catalogs/versions/${draft.catalog_version_id}`)).data; catalogVersionId.value = catalog.version_id; groupCodeColumn.value = catalog.group_code_column; await loadFile(catalog.source_file_id, 'target') } const config = draft.config_document ?? {}; sourceIdColumn.value = config.source_id_column ?? sourceIdColumn.value; if (Array.isArray(config.rules) && config.rules.length) { rules.value = config.rules; scopeMode.value = config.scope_mode ?? 'GLOBAL'; scopeSourceField.value = config.scope?.source_field ?? ''; scopeTargetField.value = config.scope?.target_field ?? ''; scopeMappingRows.value = Object.entries(config.scope?.mapping ?? {}).map(([sourceValue, targets]) => ({ source: sourceValue, targets: (targets as string[]).join(',') })); successThreshold.value = config.decision?.success_threshold ?? 88; reviewThreshold.value = config.decision?.review_threshold ?? 75; topN.value = config.decision?.top_n ?? 5 } active.value = Math.max(0, Number(draft.current_step ?? 1) - 1) }
async function restoreTask(taskId: string): Promise<void> { task.value = (await api.get(`/tasks/${taskId}`)).data; name.value = task.value.name; if (task.value.stage === 'REVIEW' && task.value.status === 'COMPLETED') { active.value = 3; await loadWorkbench() } else if (task.value.stage === 'RESULT' && task.value.status === 'COMPLETED') { active.value = 4; await loadReviewSummary() } else { active.value = 2; startPolling() } }

watch([rules, scopeMode, scopeSourceField, scopeTargetField, scopeMappingRows, successThreshold, reviewThreshold, topN, sourceIdColumn], scheduleSave, { deep: true })
onMounted(async () => { if (route.params.taskId) { try { await restoreTask(String(route.params.taskId)) } catch { await router.push('/tasks') } return } const draft = typeof route.query.draft === 'string' ? route.query.draft : ''; if (draft) { try { await restoreDraft(draft) } catch { await router.replace('/tasks/new') } } })
onBeforeUnmount(stopPolling)
</script>

<template>
  <div>
    <div class="toolbar"><div><h2>{{ name || task?.name || '新建匹配任务' }}</h2><p>选择数据 → 确认匹配规则 → 比对计算 → 人工处理 → 生成结果。</p></div></div>
    <el-steps :active="active"><el-step title="选择数据"/><el-step title="确认匹配规则"/><el-step title="比对计算"/><el-step title="人工处理"/><el-step title="生成结果"/></el-steps>
    <div v-if="active===0" class="panel"><h3>1. 选择数据</h3><el-input v-model="name" placeholder="任务名称"/><div class="uploads"><div><b>客户物料数据</b><el-upload :auto-upload="false" :show-file-list="false" :on-change="(file:any)=>upload('source',file)"><el-button>选择 Excel / CSV</el-button></el-upload><span>{{source?.original_name}}</span><el-select v-if="sourceColumns.length" v-model="sourceIdColumn" placeholder="确认客户物料编码列"><el-option v-for="column in sourceColumns" :key="column" :label="column" :value="column"/></el-select></div><div><b>集团码数据</b><el-upload :auto-upload="false" :show-file-list="false" :on-change="(file:any)=>upload('target',file)"><el-button>选择 Excel / CSV</el-button></el-upload><span>{{target?.original_name}}</span><el-select v-if="targetColumns.length" v-model="groupCodeColumn" placeholder="确认集团码列"><el-option v-for="column in targetColumns" :key="column" :label="column" :value="column"/></el-select></div></div><div class="actions"><el-button type="primary" :loading="busy" :disabled="!name||!source||!target||!sourceIdColumn||!groupCodeColumn" @click="nextStepOne">下一步：确认匹配规则</el-button></div></div>
    <div v-else-if="active===1" class="panel"><h3>2. 确认匹配规则</h3><h4>A. 匹配范围</h4><el-radio-group v-model="scopeMode"><el-radio-button value="GLOBAL">全库匹配</el-radio-button><el-radio-button value="STRICT">同组匹配</el-radio-button><el-radio-button value="MAPPED">分类映射匹配</el-radio-button></el-radio-group><div v-if="scopeMode!=='GLOBAL'" class="scope-config"><el-select v-model="scopeSourceField" placeholder="客户分类字段"><el-option v-for="column in sourceColumns" :key="column" :label="column" :value="column"/></el-select><span>→</span><el-select v-model="scopeTargetField" placeholder="集团分类字段"><el-option v-for="column in targetColumns" :key="column" :label="column" :value="column"/></el-select></div><div v-if="scopeMode==='MAPPED'" class="mapping-box"><el-table :data="scopeMappingRows" size="small"><el-table-column label="客户分类"><template #default="scope"><el-input v-model="scope.row.source" placeholder="例如 A类"/></template></el-table-column><el-table-column label="允许的集团分类（逗号分隔）"><template #default="scope"><el-input v-model="scope.row.targets" placeholder="G01,G02"/></template></el-table-column></el-table><el-button link @click="addMapping">+ 添加分类映射</el-button></div><h4>B. 字段对应与重要程度</h4><el-table :data="rules"><el-table-column label="客户字段组合" min-width="220"><template #default="scope"><el-select v-model="scope.row.source.fields" multiple collapse-tags><el-option v-for="column in sourceColumns" :key="column" :label="column" :value="column"/></el-select></template></el-table-column><el-table-column label="集团字段组合" min-width="220"><template #default="scope"><el-select v-model="scope.row.target.fields" multiple collapse-tags><el-option v-for="column in targetColumns" :key="column" :label="column" :value="column"/></el-select></template></el-table-column><el-table-column label="客户组合" min-width="150"><template #default="scope"><el-select v-model="scope.row.source.combine"><el-option label="拼接" value="concat"/><el-option label="第一个有效值" value="coalesce"/><el-option label="多个比较取最高分" value="best_of"/></el-select></template></el-table-column><el-table-column label="集团组合" min-width="150"><template #default="scope"><el-select v-model="scope.row.target.combine"><el-option label="拼接" value="concat"/><el-option label="第一个有效值" value="coalesce"/><el-option label="多个比较取最高分" value="best_of"/></el-select></template></el-table-column><el-table-column label="匹配方式" min-width="140"><template #default="scope"><el-select v-model="scope.row.matcher"><el-option label="完全一致" value="exact"/><el-option label="包含" value="contains"/><el-option label="模糊相似" value="fuzzy"/><el-option label="综合字符" value="hybrid"/><el-option label="语义相似（下一里程碑）" value="semantic" disabled/></el-select></template></el-table-column><el-table-column label="权重 0～100" width="150"><template #default="scope"><el-input-number v-model="scope.row.weight" :min="0" :max="100"/></template></el-table-column><el-table-column label="关键字段" width="100"><template #default="scope"><el-switch v-model="scope.row.critical"/></template></el-table-column><el-table-column label="操作" width="80"><template #default="scope"><el-button link type="danger" @click="removeRule(scope.$index)">删除</el-button></template></el-table-column></el-table><el-button link @click="addRule">+ 添加字段对应</el-button><h4>C. 判定阈值</h4><div class="threshold"><span>自动匹配成功阈值</span><el-input-number v-model="successThreshold" :min="1" :max="100"/><span>人工确认下限</span><el-input-number v-model="reviewThreshold" :min="0" :max="99"/><span>TopN</span><el-input-number v-model="topN" :min="1" :max="50"/></div><h4 class="click" @click="advanced=!advanced">D. 高级处理（{{advanced?'收起':'展开'}}）</h4><div v-if="advanced" class="muted">底层默认 identity，未隐式执行大小写、标点、同义词、NULL/N/A/88 判空或数值容差。完整可视化流水线编辑器仍属于下一里程碑。</div><el-alert :title="summary" :closable="false"/><div v-if="dryRunSummary" class="dry-summary">试算：自动匹配 {{dryRunSummary.matched}}｜待确认 {{dryRunSummary.review}}｜未匹配 {{dryRunSummary.unmatched}}</div><el-table v-if="dryRunRows.length" :data="dryRunRows" size="small" max-height="260"><el-table-column prop="source_id" label="客户物料"/><el-table-column prop="first_score" label="第一候选分"/><el-table-column prop="second_score" label="第二候选分"/><el-table-column prop="score_gap" label="分差"/><el-table-column label="冲突"><template #default="scope">{{scope.row.critical_conflict?'是':'否'}}</template></el-table-column><el-table-column prop="status" label="判定"/></el-table><div class="actions"><el-button @click="active=0">上一步</el-button><el-button :loading="dryRunBusy" :disabled="!rulesReady" @click="dryRun">试算100条</el-button><el-button type="primary" :disabled="!rulesReady" @click="start">下一步：开始比对</el-button></div></div>
    <div v-else-if="active===2" class="panel"><h3>3. 比对计算</h3><el-progress :percentage="Math.round(Number(progress?.progress ?? task?.progress ?? 0))"/><p>已处理 {{progress?.processed_rows ?? task?.processed_rows ?? 0}} / {{progress?.total_rows || task?.total_rows || '待统计'}}</p><el-steps direction="vertical"><el-step v-for="step in progress?.steps ?? []" :key="step.key" :title="step.label" :description="step.status==='SKIPPED'?'当前规则无需此阶段':step.status"/></el-steps><el-alert v-if="task?.status==='FAILED'" :title="task.error_message || '比对失败'" type="error" :closable="false"/><p class="muted">当前里程碑使用小规模通用扫描后端；超过安全上限会要求构建向量索引，不会构造 Source×Target 全矩阵。</p><p>配置 SHA-256：<code>{{task?.config_sha256}}</code></p></div>
    <div v-else-if="active===3" class="panel"><h3>4. 人工处理</h3><div class="stats"><b>待确认 {{reviewSummary.pending_review}}</b><span>已确认 {{reviewSummary.confirmed}}</span><span>未匹配 {{reviewSummary.unmatched}}</span><span>自动匹配 {{reviewSummary.automatic_matched}}</span></div><div class="quick"><el-button :type="filterMode==='high'?'primary':'default'" @click="setFilter('high')">90分以上且无冲突</el-button><el-button :type="filterMode==='80-90'?'primary':'default'" @click="setFilter('80-90')">80～90分</el-button><el-button :type="filterMode==='gap'?'primary':'default'" @click="setFilter('gap')">分差 &lt; 5</el-button><el-button :type="filterMode==='conflict'?'primary':'default'" @click="setFilter('conflict')">存在冲突</el-button><el-button :type="filterMode==='all'?'primary':'default'" @click="setFilter('all')">全部待确认</el-button></div><div class="quick"><el-button :disabled="!selectedRows.length" @click="batchConfirm">批量确认第一候选</el-button><el-button :disabled="!selectedRows.length" @click="batchReject">批量标记未匹配</el-button></div><el-table :data="workbenchItems" @selection-change="onSelection"><el-table-column type="selection" width="45"/><el-table-column prop="source_id" label="物料编码" min-width="130"/><el-table-column prop="top1_group_code" label="第一候选集团码" min-width="150"/><el-table-column prop="top1_score" label="第一候选分" width="110"/><el-table-column prop="second_score" label="第二候选分" width="110"/><el-table-column prop="score_gap" label="分差" width="90"/><el-table-column label="关键字段冲突" width="120"><template #default="scope"><el-tag :type="scope.row.critical_conflict?'danger':'success'">{{scope.row.critical_conflict?'有':'无'}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="260"><template #default="scope"><el-button link @click="openCandidates(scope.row)">查看候选</el-button><el-button link type="primary" @click="confirmCandidate(scope.row)">确认第一候选</el-button><el-button link type="danger" @click="rejectItem(scope.row)">标记未匹配</el-button></template></el-table-column></el-table><div class="actions"><el-button type="primary" @click="finalize">生成最终结果</el-button></div></div>
    <div v-else class="panel"><h3>5. 生成结果</h3><div class="stats"><span>总物料数 {{finalTotal}}</span><span>自动匹配 {{reviewSummary.automatic_matched}}</span><span>人工确认 {{reviewSummary.confirmed}}</span><span>未匹配 {{reviewSummary.unmatched}}</span><span>仍待确认 {{reviewSummary.pending_review}}</span></div><el-alert v-if="reviewSummary.pending_review" title="未处理的待确认记录在最终结果中保持集团码为空。" type="warning" :closable="false"/><div class="actions"><el-button v-if="!task?.result_file_id" type="primary" @click="finalize">生成最终结果 Excel</el-button><el-button v-else type="primary" @click="downloadResult">下载最终结果 Excel</el-button></div></div>
    <el-drawer v-model="drawerVisible" title="候选详情" size="72%"><div v-if="drawerItem"><p><b>客户物料：</b>{{drawerItem.source_id}}</p><el-tabs v-model="candidateIndex"><el-tab-pane v-for="(candidate,index) in candidates" :key="candidate.rank" :name="index" :label="`候选${candidate.rank} ${candidate.score.toFixed(1)}分`"/></el-tabs><div v-if="currentCandidate"><p><b>集团码：</b>{{currentCandidate.target_group_code}}　<b>得分：</b>{{currentCandidate.score.toFixed(2)}}</p><el-table :data="currentCandidate.field_scores"><el-table-column prop="rule_id" label="字段规则"/><el-table-column prop="source_value" label="客户值"/><el-table-column prop="target_value" label="集团值"/><el-table-column label="字段得分"><template #default="scope">{{(scope.row.score*100).toFixed(1)}}</template></el-table-column><el-table-column prop="weight" label="权重"/><el-table-column label="结果"><template #default="scope">{{scope.row.conflict?'冲突':'正常'}}</template></el-table-column></el-table></div><div class="actions"><el-button type="danger" @click="rejectFromDrawer">标记未匹配</el-button><el-button type="primary" :disabled="!currentCandidate" @click="confirmFromDrawer">确认当前候选</el-button></div></div></el-drawer>
  </div>
</template>
